CREATE TABLE document_templates(id text PRIMARY KEY,name text NOT NULL,document_type text NOT NULL,active_version integer NOT NULL);
CREATE TABLE document_template_versions(template_id text NOT NULL REFERENCES document_templates(id),version integer NOT NULL,definition jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(template_id,version));
CREATE TABLE generated_documents(id text PRIMARY KEY,project_id text NOT NULL REFERENCES projects(id),template_id text NOT NULL REFERENCES document_templates(id),template_version integer NOT NULL,context_revision integer NOT NULL,context_snapshot jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,title text NOT NULL,status text NOT NULL DEFAULT 'draft',output_profile jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE document_sections(id text PRIMARY KEY,document_id text NOT NULL REFERENCES generated_documents(id) ON DELETE CASCADE,section_order integer NOT NULL,definition jsonb NOT NULL,status text NOT NULL DEFAULT 'empty',revision integer NOT NULL DEFAULT 1,edited boolean NOT NULL DEFAULT false,source_refs jsonb NOT NULL DEFAULT '[]',asset_refs jsonb NOT NULL DEFAULT '[]',locked_fact_refs jsonb NOT NULL DEFAULT '[]',claims jsonb NOT NULL DEFAULT '[]',error text,context_tokens integer);
CREATE TABLE document_blocks(id text PRIMARY KEY,section_id text NOT NULL REFERENCES document_sections(id) ON DELETE CASCADE,block_order integer NOT NULL,content jsonb NOT NULL);
CREATE TABLE section_source_refs(section_id text NOT NULL REFERENCES document_sections(id) ON DELETE CASCADE,source_type text NOT NULL,source_id text NOT NULL,evidence jsonb NOT NULL,PRIMARY KEY(section_id,source_type,source_id));
CREATE TABLE generation_jobs(id text PRIMARY KEY,document_id text NOT NULL REFERENCES generated_documents(id),status text NOT NULL DEFAULT 'queued',section_ids jsonb NOT NULL,targets jsonb NOT NULL,config jsonb NOT NULL,mode text NOT NULL DEFAULT 'regenerate',source_ids jsonb NOT NULL DEFAULT '[]',processed integer NOT NULL DEFAULT 0,failed integer NOT NULL DEFAULT 0,reserved_cny double precision NOT NULL DEFAULT 0,estimated_cost_cny double precision NOT NULL DEFAULT 0,input_tokens bigint NOT NULL DEFAULT 0,output_tokens bigint NOT NULL DEFAULT 0,errors jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX generation_jobs_queue ON generation_jobs(status,created_at);
CREATE UNIQUE INDEX generation_jobs_one_active ON generation_jobs(document_id) WHERE status IN ('queued','running');
CREATE TABLE document_validation_issues(id text PRIMARY KEY,document_id text NOT NULL REFERENCES generated_documents(id) ON DELETE CASCADE,section_id text,issue jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE audit_events ALTER COLUMN document_id DROP NOT NULL;
ALTER TABLE audit_events ADD COLUMN generated_document_id text REFERENCES generated_documents(id);
CREATE INDEX generation_audit ON audit_events(generated_document_id,modified_at);
